BEGIN;

INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: easy / L1 — Written reps classified as internal evidence
(1, 'Written Representations', 'Under AU-C 580, written representations from management are classified as what type of audit evidence?', '["Internal evidence produced by the entity", "External evidence obtained from third parties", "Physical evidence directly observed by the auditor", "Analytical evidence derived from financial data comparisons"]'::jsonb, 0, 'Under AU-C 580, written representations are internal evidence because they originate from the entity''s own management. While required for every audit, they are generally less reliable than external evidence such as third-party confirmations. The second choice is incorrect because representations come from the entity itself, not an independent outside party.', 'easy', 1),

-- Q2: medium / L2 — Completeness of transactions representation
(1, 'Written Representations', 'During the 2025 audit of Meridian Supply Co., the engagement partner at Caldwell & Partners prepares the management representation letter. The controller reviews the draft and questions a specific paragraph about transactions. Under AU-C 580, management must represent that:', '["Every individual transaction was personally approved by a senior officer", "All transactions have been recorded and are reflected in the financial statements", "Each journal entry exceeding $5,000 has been independently verified", "All financial data has been reviewed by the audit committee before year-end"]'::jsonb, 1, 'AU-C 580.11 requires management to represent that all transactions have been recorded and reflected in the financial statements, supporting the completeness assertion. This ensures the auditor has a basis for concluding that no material transactions were omitted. The first choice incorrectly requires personal approval of every transaction, which is an internal control matter rather than a financial statement representation.', 'medium', 2),

-- Q3: medium / L2 — Accounting policies appropriateness representation
(1, 'Written Representations', 'Fletcher & Associates is finalizing the 2025 audit of Northgate Industries. The engagement team includes a representation about accounting policies in the management letter. Under AU-C 580, management should represent that:', '["The auditor selected all significant accounting policies used by the entity", "Only the most conservative accounting treatments were applied", "The selection and application of accounting policies are appropriate", "All accounting policy choices were approved by external regulators"]'::jsonb, 2, 'AU-C 580.11 requires management to represent that the selection and application of accounting policies are appropriate within the applicable financial reporting framework. Responsibility for selecting accounting policies rests with management, not the auditor. The first choice incorrectly assigns policy selection to the auditor, which would impair independence under the AICPA Code of Professional Conduct.', 'medium', 2),

-- Q4: medium / L3 — Contradicted representations auditor action
(1, 'Written Representations', 'During the audit of Pinnacle Corp., the auditor at Stanton & Moore obtains a written representation stating no undisclosed related-party transactions exist. However, the auditor discovers a $2.5 million loan to the CEO in the board minutes. Under AU-C 580, the auditor should:', '["Accept management''s representation because it takes precedence over other evidence", "Disregard the board minutes as informal and less authoritative than signed letters", "Issue an unmodified opinion with an emphasis-of-matter paragraph", "Evaluate the effect on the reliability of all representations and on the audit"]'::jsonb, 3, 'AU-C 580.18 requires the auditor to take appropriate action when written representations are contradicted by other audit evidence. The auditor must reconsider the reliability of all management representations and evaluate the effect on the audit opinion. The first choice is incorrect because accepting the representation without investigation would violate professional skepticism required by AU-C 200, as contradictory board minutes constitute persuasive audit evidence.', 'medium', 3),

-- Q5: hard / L4 — Combined refusal and qualification impact
(1, 'Written Representations', 'Barton & Associates is completing the December 31, 2025 audit of Crescent Holdings. Management provides the representation letter but refuses to acknowledge responsibility for internal controls and qualifies the completeness representation with ''to the best of our knowledge based on records reviewed.'' Under AU-C 580, the most appropriate response is to:', '["Disclaim an opinion due to management''s failure to provide required representations", "Accept the qualified language as a reasonable limitation and issue an unmodified opinion", "Issue a qualified opinion solely for the internal control representation refusal", "Withdraw from the engagement without issuing any report"]'::jsonb, 0, 'AU-C 580.19–.20 requires the auditor to disclaim an opinion when management does not provide one or more required written representations. Refusing to acknowledge internal control responsibility and improperly qualifying completeness both constitute failures to provide required representations. The third choice is incorrect because a qualified opinion is insufficient when the scope limitation is pervasive, and withdrawal without a report would leave the auditor''s obligations unfulfilled.', 'hard', 4),

-- Q6: easy / L1 — Form of the representation letter
(1, 'Written Representations', 'Under AU-C 580, in what form must written representations be provided to the auditor?', '["Oral statements documented in the auditor''s workpapers", "A signed written letter addressed to the auditor", "A notarized affidavit filed with regulators", "A verbal confirmation recorded during the closing meeting"]'::jsonb, 1, 'AU-C 580.14–.15 specifies that written representations must be in the form of a representation letter addressed to the auditor, signed by management with appropriate responsibilities. The first choice is incorrect because oral statements, even if documented by the auditor, do not satisfy the requirement since AU-C 580 explicitly requires a written format rather than verbal acknowledgment.', 'easy', 1),

-- Q7: medium / L2 — Laws and regulations non-compliance disclosure
(1, 'Written Representations', 'Graham & Ellis is completing the 2025 audit of Lakewood Financial Services, a state-licensed lender. The senior auditor includes a compliance representation in the management letter. Under AU-C 580, management should represent that:', '["The entity has never been subject to a regulatory examination", "All employees have signed individual compliance certifications", "All known non-compliance with laws and regulations whose effects should be considered in preparing the financial statements has been disclosed", "The entity''s compliance officer personally reviewed each transaction for legality"]'::jsonb, 2, 'AU-C 580.11 requires management to represent that all known instances of non-compliance or suspected non-compliance with laws and regulations whose effects should be considered when preparing financial statements have been disclosed to the auditor. The first choice is incorrect because it is unrelated to the specific disclosure requirement of the standard.', 'medium', 2),

-- Q8: hard / L4 — Updated reps when report is reissued
(1, 'Written Representations', 'Harper & Quinn issued an audit report for Oakmont Corp.''s December 31, 2025 financial statements on March 3, 2026. On April 15, Oakmont restates its financial statements due to a material inventory error, and the auditor agrees to reissue the report dated April 25. Under AU-C 580, the auditor should:', '["Rely on the original March 3 representation letter without changes", "Accept an oral update from management covering the restatement period", "Require only a representation about the specific inventory restatement", "Obtain an updated representation letter dated as of the new report date covering the extended period"]'::jsonb, 3, 'Under AU-C 580.15, the representation letter should be dated as of the date of the auditor''s report. When a report is reissued with a new date, the auditor must obtain updated written representations covering the entire period through the new report date. The first choice is incorrect because relying on the original letter would leave an unaddressed gap from March 3 to April 25, during which material events may have occurred.', 'hard', 4),

-- Q9: easy / L1 — Representations do not replace other procedures
(1, 'Written Representations', 'Under AU-C 580, can written representations from management replace other audit procedures?', '["No, written representations complement but do not replace other audit procedures", "Yes, if management provides detailed written assurances on the matter", "Yes, but only for immaterial account balances", "Yes, when the auditor documents the substitution in the workpapers"]'::jsonb, 0, 'AU-C 580.04 states that written representations provide necessary audit evidence but do not provide sufficient appropriate evidence on their own about the matters addressed. The auditor must corroborate representations with other procedures. The second choice incorrectly suggests detailed assurances can replace substantive testing, which contradicts the standard''s explicit limitation on the sufficiency of representations alone.', 'easy', 1),

-- Q10: medium / L2 — Going concern disclosure representation
(1, 'Written Representations', 'Morrison & Adler is auditing Cascade Ventures for the year ended December 31, 2025. The company reports recurring operating losses and negative cash flows. The representation letter should include management''s statement that:', '["The auditor is solely responsible for evaluating the entity''s ability to continue as a going concern", "Management has disclosed all information relevant to the entity''s ability to continue as a going concern", "The entity will operate profitably within the next three fiscal years", "All going concern uncertainties have been fully resolved as of the balance sheet date"]'::jsonb, 1, 'AU-C 580.11 requires management to represent that it has disclosed to the auditor all information relevant to the entity''s ability to continue as a going concern, including mitigation plans. The first choice incorrectly shifts going concern evaluation responsibility entirely to the auditor, when management must assess and disclose relevant information per ASC 205-40.', 'medium', 2),

-- Q11: hard / L4 — Inconsistent reps across multiple evidence sources
(1, 'Written Representations', 'During the 2025 audit of Sterling Manufacturing, the auditor at Whitaker & Fields obtains a representation stating no contingent liabilities exist beyond those disclosed. However, attorney response letters identify two pending lawsuits with probable losses totaling $4.2 million, and the claims register reveals three additional unresolved claims. The auditor should:', '["Accept the representation letter since management is in the best position to assess contingencies", "Ignore the attorney letters because they are addressed to the client rather than the auditor", "Evaluate the inconsistencies, discuss with management, and consider the effect on the audit opinion and reliability of all representations", "Immediately withdraw from the engagement due to presumed management dishonesty"]'::jsonb, 2, 'Under AU-C 580.18, when written representations are inconsistent with other audit evidence, the auditor must investigate the inconsistencies, discuss with management, and reconsider the reliability of all representations. Attorney confirmation letters under AU-C 501 are authoritative external evidence about litigation. The first choice is incorrect because accepting the representation without investigation would violate professional skepticism required by AU-C 200.', 'hard', 4),

-- Q12: medium / L3 — Access to records and personnel representation
(1, 'Written Representations', 'During the 2025 audit of Beacon Analytics, the CFO at Downey & Associates questions why the representation letter requires management to confirm the auditor had unrestricted access. Under AU-C 580, management must represent that it has provided the auditor with:', '["An unlimited budget for additional testing procedures", "Pre-approved workpaper templates for all audit areas", "A commitment to extend the fieldwork deadline upon request", "Access to all information, records, documentation, and personnel that management believes is relevant"]'::jsonb, 3, 'AU-C 580.11 requires management to represent that it has provided the auditor with access to all information that management believes is relevant to the preparation of the financial statements, including records, documentation, and personnel within the entity. The first choice is incorrect because budget, templates, or timelines are operational matters not addressed by the standard''s representation requirements.', 'medium', 3),

-- Q13: easy / L1 — Representation letter addressee
(1, 'Written Representations', 'Under AU-C 580, to whom should the management representation letter be addressed?', '["The engagement auditor or the audit firm", "The SEC or applicable regulatory body", "The entity''s board of directors", "The entity''s external legal counsel"]'::jsonb, 0, 'AU-C 580.14 requires the management representation letter to be addressed to the auditor. The letter is a communication from management to the engagement auditor confirming matters discussed during the audit. The second choice is incorrect because the letter is not addressed to regulators or the board; its purpose is to provide audit evidence to the auditor rather than fulfill regulatory or governance requirements.', 'easy', 1),

-- Q14: medium / L3 — Uncorrected misstatements acknowledgment
(1, 'Written Representations', 'During the 2025 audit of Hargrove Electronics, the auditor at Blake & Sterling identifies $85,000 in uncorrected misstatements that management has determined are immaterial. The representation letter should include management''s acknowledgment that:', '["The auditor assumes full responsibility for any uncorrected misstatements", "The uncorrected misstatements summarized by the auditor are immaterial both individually and in the aggregate to the financial statements as a whole", "All misstatements have been corrected before the financial statements were issued", "The uncorrected misstatements will be adjusted in the next reporting period"]'::jsonb, 1, 'AU-C 580.11 requires management to acknowledge that the effects of uncorrected misstatements are immaterial, both individually and in the aggregate, to the financial statements as a whole. A summary of these items is typically attached to the representation letter. The first choice incorrectly shifts responsibility to the auditor, while the third contradicts the premise that misstatements remain uncorrected.', 'medium', 3),

-- Q15: hard / L3 — Group audit component management representations
(1, 'Written Representations', 'Palmer & Associates serves as the group engagement partner for the consolidated audit of Vertex Holdings, which has three subsidiaries audited by component auditors. The group engagement team requests written representations from each subsidiary''s management. Under AU-C 600, this practice primarily serves to:', '["Replace the need for the group engagement team to review component auditor workpapers", "Transfer all audit risk from the group engagement partner to subsidiary management", "Obtain evidence about matters relevant to the consolidation and component financial information", "Satisfy a regulatory filing requirement for multi-entity audit reports"]'::jsonb, 2, 'Under AU-C 600.40, the group engagement team may request written representations from component management to obtain evidence about matters relevant to the group financial statements. These representations supplement the work of component auditors. The first choice is incorrect because representations do not eliminate the requirement to review component workpapers, and the second mischaracterizes the purpose as risk transfer.', 'hard', 3),

-- Q16: medium / L3 — Tailored additional representations
(1, 'Written Representations', 'During the 2025 audit of Waverly Corp., the auditor at Crawford & Long encounters an unusual derivative instrument. The engagement partner decides to add a tailored representation to the management letter addressing the derivative''s valuation methodology. Under AU-C 580, requiring representations beyond the standard list is:', '["Prohibited because the standard provides a fixed list of required topics", "Mandatory only when the item exceeds ten times materiality", "Discouraged because it places an undue burden on management", "Permitted and appropriate when the auditor considers additional representations necessary"]'::jsonb, 3, 'AU-C 580.13 permits the auditor to request additional written representations beyond those explicitly required by the standard. When the auditor identifies specific matters that warrant further management acknowledgment, tailoring the representation letter is appropriate. The first choice incorrectly characterizes AU-C 580 as a closed list, when the standard explicitly allows supplemental representations.', 'medium', 3),

-- Q17: easy / L1 — Period covered by representations
(1, 'Written Representations', 'Under AU-C 580, what period should the management representation letter cover?', '["All periods covered by the auditor''s opinion", "Only the current fiscal year", "The most recent fiscal quarter", "The twelve months following the balance sheet date"]'::jsonb, 0, 'AU-C 580.14 states that the management representation letter should cover all periods referred to in the auditor''s report. If the auditor''s opinion covers comparative financial statements, the representations must address all periods presented. The second choice is incorrect because it excludes prior periods that may be covered by the auditor''s current opinion on comparative statements.', 'easy', 1),

-- Q18: medium / L2 — Litigation claims and assessments disclosure
(1, 'Written Representations', 'Doyle & Associates is completing the 2025 audit of Summit Health Group, which faces multiple pending malpractice lawsuits. The engagement team ensures the representation letter addresses litigation. Under AU-C 580, management should represent that:', '["No lawsuits or claims will result in material financial losses", "All known actual or possible litigation and claims whose effects should be considered in the financial statements have been disclosed", "The entity''s legal counsel has certified that all pending cases will be resolved favorably", "Insurance coverage is adequate to fully offset any potential litigation losses"]'::jsonb, 1, 'AU-C 580.11 requires management to represent that all known actual or possible litigation and claims whose effects should be considered when preparing the financial statements have been disclosed to the auditor. This works alongside the AU-C 501 inquiry of the entity''s legal counsel. The first choice is incorrect because it improperly predicts litigation outcomes, while the fourth focuses on insurance adequacy rather than the required disclosure obligation.', 'medium', 2),

-- Q19: medium / L3 — Subsequent events through report date representation
(1, 'Written Representations', 'Bennett & Cole completed fieldwork for Ridgeway Inc.''s December 31, 2025 audit on February 20, 2026 and plans to date the report March 1. The engagement partner ensures the representation letter addresses post-year-end events. Under AU-C 580, management must represent that:', '["No events of any kind occurred between December 31 and the date of the letter", "Only events resulting in financial statement adjustments have been considered", "All subsequent events through the date of the representation letter requiring adjustment or disclosure have been appropriately addressed", "The auditor bears sole responsibility for identifying all subsequent events"]'::jsonb, 2, 'AU-C 580.11 and AU-C 560 require management to represent that all events occurring between the balance sheet date and the date of the representation letter that require adjustment or disclosure have been appropriately addressed. The first choice is incorrect because it is overly broad and unrealistic, while the fourth incorrectly assigns exclusive subsequent events responsibility to the auditor rather than management.', 'medium', 3),

-- Q20: hard / L4 — Management competence and knowledge for representations
(1, 'Written Representations', 'During the 2025 audit of Trident Dynamics, the auditor at Kessler & Young discovers that the CFO who signed the representation letter lacks knowledge of several significant transactions delegated to a divisional controller. The CEO claims all representations are accurate but cannot explain specific entries. Under AU-C 580, the auditor should:', '["Accept the representations because the CEO confirmed their accuracy", "Request the divisional controller co-sign the representation letter as the sole corrective action", "Conclude that the representations are automatically unreliable and immediately withdraw", "Evaluate whether management has sufficient knowledge to provide meaningful representations and consider obtaining additional representations from knowledgeable personnel"]'::jsonb, 3, 'AU-C 580.09 requires the auditor to request representations from management with appropriate responsibilities and knowledge of the matters concerned. When signatories lack knowledge of specific matters, the auditor should evaluate whether additional or different personnel should provide representations. The first choice is incorrect because it ignores the knowledge gap, while the third prematurely concludes unreliability without further investigation.', 'hard', 4),

-- Q21: medium / L2 — Fair value and estimates representation
(1, 'Written Representations', 'Langley & Price is auditing Ashford Real Estate Partners for the year ended December 31, 2025. The entity holds $45 million in investment properties measured at fair value. The representation letter should include management''s acknowledgment that:', '["The methods, significant assumptions, and data used in making accounting estimates, including fair value measurements, are appropriate", "The auditor is responsible for selecting the fair value methodology", "Fair value estimates will match actual market prices realized in subsequent periods", "All investment properties will appreciate in value during the next fiscal year"]'::jsonb, 0, 'AU-C 580.11 requires management to represent that the methods, significant assumptions, and data used in making accounting estimates are reasonable and appropriate within the financial reporting framework. This covers fair value measurements. The second choice incorrectly assigns methodology selection to the auditor, while the third provides an impossible guarantee since estimates inherently involve measurement uncertainty.', 'medium', 2),

-- Q22: easy / L1 — Written vs oral representations distinction
(1, 'Written Representations', 'Under AU-C 580, why are written representations required rather than oral statements alone?', '["Oral representations are prohibited during an audit engagement", "Written representations provide a documented record that reduces misunderstandings", "Written representations are automatically verified by independent third parties", "Oral representations cannot be provided by members of management"]'::jsonb, 1, 'AU-C 580.03 emphasizes that written representations document management''s acknowledgments, reducing the risk of misunderstandings between the auditor and management. Written evidence is more reliable than oral because it creates a verifiable record. The first choice is incorrect because oral inquiry remains a standard audit procedure under AU-C 500; however, oral statements alone do not satisfy the written representation requirement.', 'easy', 1),

-- Q23: medium / L2 — Internal control responsibility representation
(1, 'Written Representations', 'Maxwell & Stone is auditing Greenfield Logistics for the year ended December 31, 2025. The new CFO questions why the representation letter requires an acknowledgment about internal controls. Under AU-C 580, management must represent that:', '["The auditor designed and implemented all internal controls for the entity", "Internal controls will prevent all material misstatements from occurring", "Management is responsible for the design, implementation, and maintenance of internal control relevant to financial reporting", "The prior auditor approved the current internal control structure"]'::jsonb, 2, 'AU-C 580.11 requires management to acknowledge its responsibility for the design, implementation, and maintenance of internal control relevant to the preparation and fair presentation of financial statements. This reinforces that internal control is management''s responsibility. The first choice incorrectly assigns control design to the auditor, which would impair independence under the AICPA Code.', 'medium', 2),

-- Q24: medium / L2 — Side agreements and undisclosed arrangements
(1, 'Written Representations', 'Richardson & Hall is completing the 2025 audit of Keystone Builders, a general contractor with over 50 active construction contracts. The engagement partner includes a specific representation about informal arrangements. Under AU-C 580, management should represent that:', '["All contracts have been reviewed by outside legal counsel", "No construction project is currently behind schedule", "The engagement partner has personally inspected all project sites", "There are no side agreements or undisclosed arrangements that could affect the financial statements"]'::jsonb, 3, 'AU-C 580.11 supports requesting representations about completeness of information provided, including the absence of undisclosed side agreements or informal arrangements that could affect the financial statements. Side agreements may create unrecorded liabilities or contingencies. The first choice is incorrect because it addresses legal review rather than disclosure of informal arrangements to the auditor.', 'medium', 2),

-- Q25: medium / L3 — Representations required by other AU-C sections
(1, 'Written Representations', 'During the 2025 audit of Orion Capital, the engagement partner at Webber & Associates prepares the management representation letter. A staff auditor asks whether any standards beyond AU-C 580 require specific written representations. Under auditing standards, additional written representations may be required by:', '["Other AU-C sections addressing specific areas such as AU-C 550 for related parties and AU-C 560 for subsequent events", "Only federal tax authorities requiring formal management attestation letters", "The entity''s external legal counsel as a condition of the engagement letter", "The prior year auditor as part of the predecessor-successor communication process"]'::jsonb, 0, 'AU-C 580.A1 notes that written representations are required by many other AU-C sections in addition to AU-C 580. For example, AU-C 550 requires representations about related parties and AU-C 560 addresses subsequent events. These section-specific representations supplement the general requirements of AU-C 580. The second choice is incorrect because tax authorities and prior auditors do not dictate the content of management representation letters.', 'medium', 3),

-- Q26: easy / L1 — To the best of our knowledge qualifier
(1, 'Written Representations', 'Under AU-C 580, when is the phrase ''to the best of our knowledge and belief'' appropriate in written representations?', '["It is never appropriate and automatically invalidates the representation", "It is appropriate for representations involving matters that require management''s judgment or are not directly verifiable", "It is required for every representation in the letter", "It is appropriate only when the auditor requests it in writing"]'::jsonb, 1, 'AU-C 580.A8 recognizes that some written representations appropriately include the phrase ''to the best of our knowledge and belief'' for matters involving management''s judgment or information not directly verifiable. However, representations about management''s responsibility for the financial statements require unqualified acknowledgment. The first choice is incorrect because the standard explicitly contemplates this language for appropriate matters.', 'easy', 1),

-- Q27: easy / L1 — Minimum signatories on representation letter
(1, 'Written Representations', 'Under AU-C 580, who are the expected signatories on the management representation letter?', '["The internal audit director and the external auditor", "The audit committee chair and the general counsel", "The chief executive officer and the chief financial officer or their equivalents", "All members of the board of directors"]'::jsonb, 2, 'AU-C 580.16 states that the auditor should request written representations from management with appropriate responsibilities for the financial statements and knowledge of the matters concerned—typically the CEO and CFO or their equivalents. The first choice incorrectly includes the external auditor as a signatory, while the fourth imposes an excessive requirement not contemplated by the standard.', 'easy', 1),

-- Q28: medium / L3 — Pledged or encumbered assets disclosure
(1, 'Written Representations', 'During the 2025 audit of Hartfield Manufacturing, the auditor at Reynolds & Grant discovers that certain equipment is pledged as collateral for a $3 million line of credit. The engagement partner considers the representation letter implications. Under AU-C 580, management must represent that:', '["All equipment has been appraised by an independent valuation firm", "No assets are encumbered or subject to any restrictions whatsoever", "The entity''s insurance covers the full replacement value of pledged assets", "All liens, encumbrances, and pledges of assets have been properly disclosed in the financial statements"]'::jsonb, 3, 'AU-C 580.11 supports representations about the completeness of disclosure, including liens and encumbrances on assets. Proper disclosure of pledged assets is essential for financial statement users to understand restrictions on entity resources. The second choice is incorrect because it is overly broad and unrealistic for most entities, while the first focuses on appraisal rather than the required financial statement disclosure obligation.', 'medium', 3),

-- Q29: hard / L4 — First-year audit additional representations
(1, 'Written Representations', 'Chen & Sullivan is performing the initial audit of Athena Biotech for the year ended December 31, 2025. The company was previously unaudited and has no predecessor auditor. The engagement partner considers whether first-year circumstances affect the representation letter. Compared to a recurring engagement, the first-year representation letter should:', '["Include representations about opening balances and completeness of information about prior-period matters that may affect the current year", "Be limited to current-year matters only since no predecessor auditor exists", "Require signatures from all employees who held financial positions during prior years", "Include a representation that all prior-year financial statements were materially correct"]'::jsonb, 0, 'Under AU-C 510.09 and AU-C 580, initial audit engagements require the auditor to obtain representations about opening balances and prior-period matters that may affect the current period. Management must represent the completeness of information about prior-period events. The second choice incorrectly limits scope, while the fourth asks management to certify accuracy of unaudited statements, which is not a standard requirement.', 'hard', 4),

-- Q30: easy / L2 — Fraud prevention and detection controls responsibility
(1, 'Written Representations', 'Allen & Shaw is completing the 2025 audit of Crestview Supply. A new staff auditor reviews the representation letter and notices a paragraph about fraud. Under AU-C 580, management must represent responsibility for:', '["Guaranteeing that no fraud has ever occurred within the entity", "The design and implementation of internal controls to prevent and detect fraud", "Personally investigating every employee suspected of misconduct", "Hiring an independent forensic accountant for every reporting period"]'::jsonb, 1, 'AU-C 580.11 requires management to represent its responsibility for the design, implementation, and maintenance of internal control to prevent and detect fraud. This representation is distinct from guaranteeing no fraud occurred. The first choice is incorrect because no entity can guarantee the complete absence of fraud; the standard focuses on management''s responsibility for preventive and detective controls.', 'easy', 2)
;

COMMIT;
